 29→// Droid implements the Agent interface for Factory AI Droid.
 30→type Droid struct{}
 31→
 32→func (d *Droid) Name() string               { return "factoryai-droid" }
 33→func (d *Droid) Binary() string             { return "droid" }
 34→func (d *Droid) EntireAgent() string        { return "factoryai-droid" }
 35→func (d *Droid) PromptPattern() string      { return `[│|] >` }
 36→func (d *Droid) TimeoutMultiplier() float64 { return 2.0 }
