 90→type droidStartupConfig struct {
 91→	attempts          int
 92→	timeout           time.Duration
 93→	warmup            bool
 94→	handshakeTimeout  time.Duration
 95→	handshakeAttempts int
 96→	handshakeRestarts int
 97→}
 98→
 99→func droidStartupConfigFromEnv() droidStartupConfig {
100→	cfg := droidStartupConfig{
101→		attempts:          2,
102→		timeout:           60 * time.Second,
103→		warmup:            false,
104→		handshakeTimeout:  45 * time.Second,
105→		handshakeAttempts: 2,
106→		handshakeRestarts: 1,
107→	}
108→
109→	if os.Getenv("CI") != "" {
110→		cfg.attempts = 3
111→		cfg.timeout = 90 * time.Second
112→		cfg.warmup = true
113→	}
114→
115→	if raw := os.Getenv("E2E_DROID_STARTUP_ATTEMPTS"); raw != "" {
116→		if v, err := strconv.Atoi(raw); err == nil && v > 0 {
117→			cfg.attempts = v
118→		}
119→	}
120→	if raw := os.Getenv("E2E_DROID_STARTUP_TIMEOUT"); raw != "" {
121→		if v, err := time.ParseDuration(raw); err == nil && v > 0 {
122→			cfg.timeout = v
123→		}
124→	}
125→	if raw := os.Getenv("E2E_DROID_WARMUP"); raw != "" {
126→		switch strings.ToLower(strings.TrimSpace(raw)) {
127→		case "0", "false", "off", "no":
128→			cfg.warmup = false
129→		case "1", "true", "on", "yes":
130→			cfg.warmup = true
131→		}
132→	}
133→	if raw := os.Getenv("E2E_DROID_HANDSHAKE_TIMEOUT"); raw != "" {
134→		if v, err := time.ParseDuration(raw); err == nil && v > 0 {
135→			cfg.handshakeTimeout = v
136→		}
137→	}
138→	if raw := os.Getenv("E2E_DROID_HANDSHAKE_ATTEMPTS"); raw != "" {
139→		if v, err := strconv.Atoi(raw); err == nil && v > 0 {
140→			cfg.handshakeAttempts = v
141→		}
142→	}
143→	if raw := os.Getenv("E2E_DROID_HANDSHAKE_RESTARTS"); raw != "" {
144→		if v, err := strconv.Atoi(raw); err == nil && v >= 0 {
145→			cfg.handshakeRestarts = v
146→		}
147→	}
148→
149→	return cfg
150→}
