152→func droidStartupReadyPattern() string {
153→	return `(?s)([│|] >|ENTER to send.*Current folder:|Current folder:.*ENTER to send)`
154→}
155→
156→func droidPromptReady(content string) bool {
157→	return strings.Contains(content, "│ >") ||
158→		strings.Contains(content, "| >")
159→}
160→
161→func droidStartupMarkersReady(content string) bool {
162→	return strings.Contains(content, "ENTER to send") &&
163→		strings.Contains(content, "Current folder:")
164→}
