175→func (d *Droid) Bootstrap() error {
176→	apiKey := os.Getenv("ANTHROPIC_API_KEY")
177→	if apiKey != "" {
178→		home, err := os.UserHomeDir()
179→		if err != nil {
180→			return fmt.Errorf("get home dir: %w", err)
181→		}
182→		dir := filepath.Join(home, ".factory")
183→		if err := os.MkdirAll(dir, 0o755); err != nil {
184→			return fmt.Errorf("mkdir %s: %w", dir, err)
185→		}
186→
187→		settingsPath := filepath.Join(dir, "settings.json")
188→
189→		// Read existing settings to merge (hooks may already be configured
190→		// in the repo-local .factory/settings.json, but the global config
191→		// at ~/.factory/settings.json might have other pre-existing entries).
192→		var settings droidSettings
193→		if data, readErr := os.ReadFile(settingsPath); readErr == nil {
194→			// Best-effort merge: ignore parse errors and start fresh
195→			_ = json.Unmarshal(data, &settings)
196→		}
197→
198→		// Replace or add the BYOK model entry.
199→		byokModel := droidCustomModel{
200→			DisplayName:    droidCustomModelDisplayName,
201→			Model:          droidCustomModelBaseID,
202→			BaseURL:        "https://api.anthropic.com",
203→			APIKey:         apiKey,
204→			Provider:       "anthropic",
205→			MaxOutputToken: 8192,
206→		}
207→
208→		found := false
209→		for i, m := range settings.CustomModels {
210→			if m.Model == byokModel.Model {
211→				settings.CustomModels[i] = byokModel
212→				found = true
213→				break
214→			}
215→		}
216→		if !found {
217→			settings.CustomModels = append(settings.CustomModels, byokModel)
218→		}
219→
220→		// Set the BYOK model as the default for interactive mode.
221→		if settings.SessionDefaultSettings == nil {
222→			settings.SessionDefaultSettings = &droidSessionDefaults{}
223→		}
224→		settings.SessionDefaultSettings.Model = droidCustomModelBaseID
225→
226→		data, err := json.MarshalIndent(settings, "", "  ")
227→		if err != nil {
228→			return fmt.Errorf("marshal settings: %w", err)
229→		}
230→		if err := os.WriteFile(settingsPath, data, 0o644); err != nil {
231→			return fmt.Errorf("write settings: %w", err)
232→		}
233→	}
234→
235→	cfg := droidStartupConfigFromEnv()
236→	if !cfg.warmup {
237→		return nil
238→	}
239→	if err := d.warmup(); err != nil {
240→		fmt.Fprintf(os.Stderr, "droid warmup failed (non-fatal): %v\n", err)
241→	}
242→	return nil
243→}
