245→func (d *Droid) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
246→	cfg := &runConfig{Model: defaultDroidModel}
247→	for _, o := range opts {
248→		o(cfg)
249→	}
250→
251→	model := cfg.Model
252→	if model == "" {
253→		model = defaultDroidModel
254→	}
255→
256→	args := []string{"exec", "--skip-permissions-unsafe", "--model", model, prompt}
257→	displayArgs := []string{"exec", "--skip-permissions-unsafe", "--model", model, fmt.Sprintf("%q", prompt)}
258→
259→	cmd := exec.CommandContext(ctx, d.Binary(), args...)
260→	cmd.Dir = dir
261→	cmd.Stdin = nil
262→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
263→	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
264→	cmd.Cancel = func() error {
265→		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
266→	}
267→	cmd.WaitDelay = 5 * time.Second
268→
269→	var stdout, stderr strings.Builder
270→	cmd.Stdout = &stdout
271→	cmd.Stderr = &stderr
272→
273→	err := cmd.Run()
274→	exitCode := 0
275→	if err != nil {
276→		exitErr := &exec.ExitError{}
277→		if errors.As(err, &exitErr) {
278→			exitCode = exitErr.ExitCode()
279→		} else {
280→			exitCode = -1
281→		}
282→	}
283→
284→	return Output{
285→		Command:  d.Binary() + " " + strings.Join(displayArgs, " "),
286→		Stdout:   stdout.String(),
287→		Stderr:   stderr.String(),
288→		ExitCode: exitCode,
289→	}, err
290→}
