292→func (d *Droid) StartSession(ctx context.Context, dir string) (Session, error) {
293→	_ = ctx
294→	cfg := droidStartupConfigFromEnv()
295→
296→	var s *TmuxSession
297→	var lastErr error
298→	handshakeRestartsLeft := cfg.handshakeRestarts
299→	for attempt := range cfg.attempts {
300→		name := fmt.Sprintf("droid-test-%d", time.Now().UnixNano())
301→		var err error
302→		s, err = NewTmuxSession(name, dir, nil, "env", "ENTIRE_TEST_TTY=0", d.Binary())
303→		if err != nil {
304→			return nil, err
305→		}
306→
307→		// Resize so droid's full-screen TUI has room to render the prompt area.
308→		// The default 80x24 pane is too small — droid's splash + prompt needs ~30 lines.
309→		_ = exec.Command("tmux", "resize-window", "-t", name, "-x", "200", "-y", "50").Run()
310→
311→		// Phase 1: detect startup readiness (prompt OR known startup markers).
312→		if _, err := s.WaitFor(droidStartupReadyPattern(), cfg.timeout); err != nil {
313→			_ = s.Close()
314→			if attempt < cfg.attempts-1 {
315→				lastErr = err
316→				fmt.Fprintf(os.Stderr, "droid startup attempt %d/%d failed during readiness wait: %s\n", attempt+1, cfg.attempts, err)
317→				time.Sleep(time.Duration(attempt+1) * 2 * time.Second)
318→				continue
319→			}
320→			return nil, fmt.Errorf("droid failed to start after %d attempts: %w", cfg.attempts, err)
321→		}
322→
323→		// Phase 2: active handshake verifies the session can receive and answer prompts.
324→		handshakeOK := false
325→		for hAttempt := 1; hAttempt <= cfg.handshakeAttempts; hAttempt++ {
326→			token, err := d.performHandshake(s, cfg.handshakeTimeout)
327→			if err == nil {
328→				handshakeOK = true
329→				fmt.Fprintf(os.Stderr, "droid startup handshake succeeded on attempt %d/%d (token=%s)\n", hAttempt, cfg.handshakeAttempts, token)
330→				break
331→			}
332→			lastErr = err
333→			fmt.Fprintf(os.Stderr, "droid handshake attempt %d/%d failed: %v\n", hAttempt, cfg.handshakeAttempts, err)
334→		}
335→		if handshakeOK {
336→			s.stableAtSend = ""
337→			return s, nil
338→		}
339→
340→		content := s.Capture()
341→		_ = s.Close()
342→
343→		state := fmt.Sprintf("prompt=%t startup_markers=%t", droidPromptReady(content), droidStartupMarkersReady(content))
344→		wrappedErr := fmt.Errorf("startup handshake failed (%s): %w", state, lastErr)
345→		if handshakeRestartsLeft > 0 {
346→			handshakeRestartsLeft--
347→			lastErr = wrappedErr
348→			fmt.Fprintf(os.Stderr, "droid startup restarting session after handshake failure (%d restart(s) left): %v\n", handshakeRestartsLeft, wrappedErr)
349→			continue
350→		}
351→		if attempt < cfg.attempts-1 {
352→			lastErr = wrappedErr
353→			fmt.Fprintf(os.Stderr, "droid startup attempt %d/%d failed after handshake retries: %v\n", attempt+1, cfg.attempts, wrappedErr)
354→			time.Sleep(time.Duration(attempt+1) * 2 * time.Second)
355→			continue
356→		}
357→		return nil, fmt.Errorf("droid failed to start after %d attempts: %w", cfg.attempts, wrappedErr)
358→	}
359→	return nil, fmt.Errorf("droid failed to start after %d attempts: %w", cfg.attempts, lastErr)
360→}
361→
362→func (d *Droid) performHandshake(s *TmuxSession, timeout time.Duration) (string, error) {
363→	token := droidHandshakeToken()
364→	if err := s.Send(droidHandshakePrompt(token)); err != nil {
365→		return token, fmt.Errorf("send handshake prompt: %w", err)
366→	}
367→	if _, err := s.WaitFor(regexp.QuoteMeta(token), timeout); err != nil {
368→		return token, fmt.Errorf("wait for handshake token: %w", err)
369→	}
370→	if _, err := s.WaitFor(d.PromptPattern(), timeout); err != nil {
371→		return token, fmt.Errorf("wait for prompt after handshake: %w", err)
372→	}
373→	return token, nil
374→}
375→
376→func (d *Droid) warmup() error {
377→	const warmupAttempts = 2
378→	const warmupTimeout = 30 * time.Second
379→
380→	dir, err := os.MkdirTemp("", "droid-warmup-*")
381→	if err != nil {
382→		return fmt.Errorf("create warmup dir: %w", err)
383→	}
384→	defer func() { _ = os.RemoveAll(dir) }()
385→
386→	var lastErr error
387→	for attempt := range warmupAttempts {
388→		ctx, cancel := context.WithTimeout(context.Background(), warmupTimeout)
389→		out, err := d.RunPrompt(ctx, dir, "Reply with OK.", WithModel(defaultDroidModel))
390→		cancel()
391→		if err == nil {
392→			return nil
393→		}
394→
395→		lastErr = fmt.Errorf("%w (stderr: %s)", err, strings.TrimSpace(out.Stderr))
396→		if attempt < warmupAttempts-1 && d.IsTransientError(out, err) {
397→			time.Sleep(time.Duration(attempt+1) * 2 * time.Second)
398→			continue
399→		}
400→		break
401→	}
402→	return lastErr
403→}
