 16→	"github.com/entireio/cli/e2e/agents"
 17→	"github.com/entireio/cli/e2e/entire"
 18→)
 19→
 20→const droidRepoSettingsPath = ".factory/settings.json"
 21→
 22→// RepoState holds the working state for a single test's cloned repository.
 23→type RepoState struct {
 24→	Agent            agents.Agent
 25→	Dir              string
 26→	ArtifactDir      string
 27→	HeadBefore       string
 28→	CheckpointBefore string
 29→	ConsoleLog       *os.File
 30→	session          agents.Session // interactive session, if started via StartSession
 31→	skipArtifacts    bool           // suppresses artifact capture on scenario restart
 32→	lastSentInput    string         // tracks last input for retry-on-timeout
 33→}
 34→
 35→// SetupRepo creates a fresh git repository in a temporary directory, seeds it
 36→// with an initial commit, and runs `entire enable` for the given agent.
 37→// Artifact capture is registered as a cleanup function.
 38→//
 39→// When E2E_KEEP_REPOS is set, the temporary directory is not cleaned up
 40→// so it can be inspected after the test. A symlink in the artifact dir
 41→// points to the preserved repo.
 42→func SetupRepo(t *testing.T, agent agents.Agent) *RepoState {
 43→	t.Helper()
 44→
 45→	keepRepos := os.Getenv("E2E_KEEP_REPOS") != ""
 46→
 47→	// Always use os.MkdirTemp instead of t.TempDir(). Go's t.TempDir()
 48→	// creates nested subdirectories (TestName.../001/) whose structure
 49→	// confuses some agents' (e.g. opencode) working-directory resolution.
 50→	dir, err := os.MkdirTemp("", "e2e-repo-*")
 51→	if err != nil {
 52→		t.Fatalf("create temp dir: %v", err)
 53→	}
 54→	if keepRepos {
 55→		t.Logf("E2E_KEEP_REPOS: repo will be preserved at %s", dir)
 56→	} else {
 57→		t.Cleanup(func() { os.RemoveAll(dir) })
 58→	}
 59→
 60→	// Resolve symlinks (macOS: /var -> /private/var) so paths match
 61→	// what agent CLIs see when they resolve their own CWD.
 62→	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
 63→		dir = resolved
 64→	}
 65→
 66→	Git(t, dir, "init")
 67→	Git(t, dir, "config", "user.name", "E2E Test")
 68→	Git(t, dir, "config", "user.email", "e2e@test.local")
 69→	Git(t, dir, "commit", "--allow-empty", "-m", "initial commit")
 70→
 71→	entire.Enable(t, dir, agent.EntireAgent())
 72→	if agent.Name() == "factoryai-droid" {
 73→		if err := configureDroidRepoSettings(dir); err != nil {
 74→			t.Fatalf("configure droid repo settings: %v", err)
 75→		}
 76→	}
 77→	PatchSettings(t, dir, map[string]any{"log_level": "debug"})
 78→
 79→	// OpenCode's non-interactive mode auto-rejects external_directory permission
 80→	// since there's no user to prompt. Write a config to allow it.
 81→	if agent.Name() == "opencode" {
 82→		cfg := `{"$schema": "https://opencode.ai/config.json", "permission": {"external_directory": "allow"}}`
 83→		if key := os.Getenv("ANTHROPIC_API_KEY"); key != "" {
 84→			cfg = fmt.Sprintf(`{"$schema": "https://opencode.ai/config.json", "permission": {"external_directory": "allow"}, "provider": {"anthropic": {"options": {"apiKey": %q}}}}`, key)
 85→		}
 86→		if err := os.WriteFile(filepath.Join(dir, "opencode.json"), []byte(cfg+"\n"), 0o644); err != nil {
 87→			t.Fatalf("write opencode.json: %v", err)
 88→		}
 89→	}
 90→
 91→	// Create artifact dir eagerly so console.log is written to disk
 92→	// incrementally. Even if the test is killed by a global timeout,
 93→	// partial output survives.
 94→	artDir := artifactDir(t)
 95→	consoleLog, err := os.Create(filepath.Join(artDir, "console.log"))
 96→	if err != nil {
 97→		t.Fatalf("create console.log: %v", err)
 98→	}
 99→
100→	state := &RepoState{
101→		Agent:            agent,
102→		Dir:              dir,
103→		ArtifactDir:      artDir,
104→		HeadBefore:       GitOutput(t, dir, "rev-parse", "HEAD"),
105→		CheckpointBefore: GitOutput(t, dir, "rev-parse", "entire/checkpoints/v1"),
106→		ConsoleLog:       consoleLog,
107→	}
108→
109→	t.Cleanup(func() {
110→		_ = consoleLog.Close()
111→		if !state.skipArtifacts {
112→			CaptureArtifacts(t, state)
113→		}
114→	})
115→
116→	return state
117→}
