119→func configureDroidRepoSettings(repoDir string) error {
120→	home, err := os.UserHomeDir()
121→	if err != nil {
122→		return fmt.Errorf("get home dir: %w", err)
123→	}
124→
125→	globalSettingsPath := filepath.Join(home, ".factory", "settings.json")
126→	repoSettingsPath := filepath.Join(repoDir, droidRepoSettingsPath)
127→
128→	if err := mergeDroidCustomModels(globalSettingsPath, repoSettingsPath); err != nil {
129→		return err
130→	}
131→	if err := ensureGitInfoExcludeContains(repoDir, droidRepoSettingsPath); err != nil {
132→		return fmt.Errorf("exclude droid settings from git: %w", err)
133→	}
134→	return nil
135→}
136→
137→func mergeDroidCustomModels(globalSettingsPath, repoSettingsPath string) error {
138→	globalSettings, err := loadJSONMap(globalSettingsPath, "global droid settings")
139→	if err != nil {
140→		return err
141→	}
142→
143→	customModels, ok := globalSettings["customModels"]
144→	if !ok {
145→		return fmt.Errorf(
146→			"global droid settings at %s missing customModels; repo-local %s shadows global settings",
147→			globalSettingsPath,
148→			repoSettingsPath,
149→		)
150→	}
151→
152→	var models []json.RawMessage
153→	if err := json.Unmarshal(customModels, &models); err != nil {
154→		return fmt.Errorf("parse customModels in %s: %w", globalSettingsPath, err)
155→	}
156→	if len(models) == 0 {
157→		return fmt.Errorf("global droid settings at %s has empty customModels", globalSettingsPath)
158→	}
159→
160→	repoSettings, err := loadJSONMap(repoSettingsPath, "repo-local droid settings")
161→	if err != nil {
162→		return err
163→	}
164→	repoSettings["customModels"] = customModels
165→
166→	out, err := json.MarshalIndent(repoSettings, "", "  ")
167→	if err != nil {
168→		return fmt.Errorf("marshal repo-local droid settings: %w", err)
169→	}
170→	out = append(out, '\n')
171→
172→	if err := os.WriteFile(repoSettingsPath, out, 0o600); err != nil {
173→		return fmt.Errorf("write repo-local droid settings %s: %w", repoSettingsPath, err)
174→	}
175→	return nil
176→}
177→
178→func loadJSONMap(path, description string) (map[string]json.RawMessage, error) {
179→	data, err := os.ReadFile(path)
180→	if err != nil {
181→		return nil, fmt.Errorf("read %s at %s: %w", description, path, err)
182→	}
183→
184→	var parsed map[string]json.RawMessage
185→	if err := json.Unmarshal(data, &parsed); err != nil {
186→		return nil, fmt.Errorf("parse %s at %s: %w", description, path, err)
187→	}
188→	if parsed == nil {
