290→// runScenario runs the test function and recovers from errScenarioRestart
291→// panics triggered by transient API errors in RunPrompt. Returns true if
292→// the scenario should be restarted with a fresh repository.
293→func runScenario(t *testing.T, s *RepoState, ctx context.Context, fn func(t *testing.T, s *RepoState, ctx context.Context)) (restarted bool) {
294→	t.Helper()
295→	defer func() {
296→		if r := recover(); r != nil {
297→			if _, ok := r.(errScenarioRestart); ok {
298→				restarted = true
299→				return
300→			}
301→			panic(r) // re-panic for unexpected panics
302→		}
303→	}()
304→	fn(t, s, ctx)
305→	return false
306→}
307→
308→const maxScenarioRestarts = 2 // restart up to 2 times = 3 total attempts
309→
310→// errScenarioRestart is panicked by RunPrompt when a transient API error is
311→// detected. ForEachAgent recovers from this panic and restarts the test
312→// scenario with a fresh repository, avoiding stale CLI state from the failed
313→// attempt.
314→type errScenarioRestart struct {
315→	msg string
316→}
317→
318→// RunPrompt runs an agent prompt, logs the command and output to ConsoleLog,
319→// and returns the result. If the agent reports a transient API error, it
320→// panics with errScenarioRestart to trigger a full scenario restart in
321→// ForEachAgent (see runScenario).
322→func (s *RepoState) RunPrompt(t *testing.T, ctx context.Context, prompt string, opts ...agents.Option) (agents.Output, error) {
323→	t.Helper()
324→	out, err := s.Agent.RunPrompt(ctx, s.Dir, prompt, opts...)
325→	s.logPromptResult(out)
326→
327→	if err != nil && s.Agent.IsTransientError(out, err) {
328→		errMsg := fmt.Sprintf("transient API error (stderr: %s)", strings.TrimSpace(out.Stderr))
329→		t.Logf("%s — restarting scenario", errMsg)
330→		fmt.Fprintf(s.ConsoleLog, "> [transient] %s — restarting scenario\n", errMsg)
331→		panic(errScenarioRestart{msg: errMsg})
332→	}
333→
334→	return out, err
335→}
