366→// WaitFor waits for a pattern in the interactive session's pane and logs the
367→// pane content to ConsoleLog after the wait completes (success or failure).
368→func (s *RepoState) WaitFor(t *testing.T, session agents.Session, pattern string, timeout time.Duration) {
369→	t.Helper()
370→	scaled := time.Duration(float64(timeout) * s.Agent.TimeoutMultiplier())
371→	content, err := session.WaitFor(pattern, scaled)
372→	fmt.Fprintf(s.ConsoleLog, "> pane after WaitFor(%q):\n%s\n", pattern, content)
373→	if err != nil {
374→		if s.shouldUseDroidHandshakeRecovery(pattern) {
375→			t.Logf("WaitFor(%q) timed out; attempting droid handshake recovery", pattern)
376→			fmt.Fprintf(s.ConsoleLog, "> [recovery] attempting droid handshake after WaitFor(%q) timeout\n", pattern)
377→			content, recoveryErr := s.recoverDroidPromptTimeoutWithHandshake(session, pattern, scaled)
378→			fmt.Fprintf(s.ConsoleLog, "> pane after handshake recovery WaitFor(%q):\n%s\n", pattern, content)
379→			if recoveryErr == nil {
380→				return
381→			}
382→			err = fmt.Errorf("wait failed: %w; handshake recovery failed: %v", err, recoveryErr)
383→		}
384→		if err != nil {
385→			t.Fatalf("WaitFor(%q): %v", pattern, err)
386→		}
387→	}
388→}
