505→// CheckpointIDs lists all checkpoint IDs from the tree at the tip of the
506→// checkpoint branch. It parses the two-level directory structure
507→// ({prefix}/{suffix}/metadata.json) and returns the concatenated IDs.
508→func CheckpointIDs(t *testing.T, dir string) []string {
509→	t.Helper()
510→	out := gitOutputSafe(dir, "ls-tree", "-r", "--name-only", "entire/checkpoints/v1")
511→	if out == "" {
512→		return nil
513→	}
514→	seen := map[string]bool{}
515→	var ids []string
516→	for _, line := range strings.Split(strings.TrimSpace(out), "\n") {
517→		// Match {prefix}/{suffix}/metadata.json (top-level, not session-level)
518→		parts := strings.Split(line, "/")
519→		if len(parts) == 3 && parts[2] == "metadata.json" {
520→			id := parts[0] + parts[1]
521→			if !seen[id] {
522→				seen[id] = true
523→				ids = append(ids, id)
524→			}
525→		}
526→	}
527→	return ids
528→}
