566→// WaitForSessionMetadata polls until session metadata exists on the checkpoint
567→// branch for the given checkpoint ID and session index, then returns it.
568→// This handles the race where the checkpoint branch advances before session
569→// metadata is fully committed.
570→func WaitForSessionMetadata(t *testing.T, dir string, checkpointID string, sessionIndex int, timeout time.Duration) SessionMetadata {
571→	t.Helper()
572→
573→	path := fmt.Sprintf("%s/%d/metadata.json", CheckpointPath(checkpointID), sessionIndex)
574→	blob := "entire/checkpoints/v1:" + path
575→
576→	deadline := time.Now().Add(timeout)
577→	for time.Now().Before(deadline) {
578→		raw := gitOutputSafe(dir, "show", blob)
579→		if raw != "" {
580→			var meta SessionMetadata
581→			if err := json.Unmarshal([]byte(raw), &meta); err != nil {
582→				t.Fatalf("unmarshal session metadata from %s: %v", blob, err)
583→			}
584→			return meta
585→		}
586→		time.Sleep(500 * time.Millisecond)
587→	}
588→	t.Fatalf("session metadata %s did not appear within %s", blob, timeout)
589→	return SessionMetadata{}
590→}
