		return "", fmt.Errorf("send handshake prompt: %w", err)
	}

	content, err := session.WaitFor(regexp.QuoteMeta(token), timeout)
	fmt.Fprintf(s.ConsoleLog, "> pane after handshake token wait:\n%s\n", content)
	if err != nil {
		return content, fmt.Errorf("wait for handshake token: %w", err)
	}

	// Token echo proves the session is responsive. The WaitFor settle
	// mechanism ensures the response has stabilized. No additional prompt
	// pattern wait needed — it was the source of CI flakiness.
	return content, nil
}

