	cfg := droidStartupConfigFromEnv()

	if cfg.timeout != 135*time.Second {
		t.Fatalf("timeout=%s, want 2m15s", cfg.timeout)
	}
	if cfg.attempts != 5 {
		t.Fatalf("attempts=%d, want 5", cfg.attempts)
	}
	if cfg.warmup {
		t.Fatal("warmup=true, want false")
	}
	if cfg.handshakeTimeout != 30*time.Second {
		t.Fatalf("handshakeTimeout=%s, want 30s", cfg.handshakeTimeout)
	}
	if cfg.handshakeAttempts != 4 {
		t.Fatalf("handshakeAttempts=%d, want 4", cfg.handshakeAttempts)
	}
	if cfg.handshakeRestarts != 2 {
		t.Fatalf("handshakeRestarts=%d, want 2", cfg.handshakeRestarts)
	}
}

